    afterReading: ['أنجز التحدي السريع بجدول «قبل / بعد».', 'التركيز اللغوي: «لم ننتظرْ حتى يذهبَ» (النشاط 1)، ثم السبب والواجب والفعل (النشاط 2)، ثم تصحيح المثنى والنون (النشاط 3).', 'اكتب خمس جمل عن روتين تغيّر بسبب المساعدة (النشاط 4).'],
    lessonPlan: '0–5 تهيئة: كيف نعرف أن شخصًا يحتاج إلى مساعدة؟ إجابتان على السبورة؛ 5–11 استماع ثم قراءة صامتة، ويجيب كل ثنائي عن سؤال السبورة من النص؛ 11–18 جدول «قبل المساعدة / بعدها» في ثنائيات بعبارة لكل خانة، ثم قراءة جهرية مضبوطة لكلام الفتاتين وجوابهما لأبيهما مع الانتباه إلى «علينا أنْ نأخذَ» و«لم ننتظرْ»؛ 18–22 التحدي السريع؛ 22–30 التركيز اللغوي: النشاط 1 اكتشافًا جماعيًّا (هل انتظرتا هذه المرة؟)، والنشاطان 2–3 في ثنائيات مع التعليل بكلمة (مجزوم، منصوب، مثنى)؛ 30–38 استعمال: يصف المتعلم روتينًا مدرسيًّا (انتظار آلة التصوير، أو ترتيب الكراسي بعد حفل) تغيّر عندما ساعده أحد، في خمس جمل فيها «علينا أنْ» و«حتى» و«لم + مجزوم»، ويقرأ زميل فقرته؛ 38–40 بطاقة الخروج',
    discussionPoints: ['ما الكلمات التي تبيّن أن الفتاتين تحتاجان إلى المساعدة؟', 'كيف عرف الأب أن شيئًا غير عادي حدث؟', 'لماذا كانت الفتاتان تخرجان وحدهما لسقي الغنم كما تقول الجملة الأخيرة؟'],
    interactiveTips: ['استخدم نقطة «انتظار الدور» لكلامهما، ونقطة «مساعدة الآخرين» لفعل موسى ونتيجته.', 'أعد تشغيل كلام الفتاتين قبل أيّ حديث عن قيمة المساعدة.', 'ارفع بطاقتين: «علينا أنْ» / «لم ننتظرْ» في أثناء إعادة سرد اليوم.'],
    differentiation: { strugglingLearners: 'جدول بإطارين مشكولين: «قبل المساعدة: علينا أنْ ____َ حتى ____َ ____.» / «بعد المساعدة: لم ____ْ.»', fastFinishers: 'اكتب ست جمل عن روتين تزيل فيه المساعدة واجبًا واحدًا ولا تزيل المسؤولية كلها، مستعملًا «لذلك» و«علينا أنْ» و«حتى» و«لم» ومثنى مضبوطًا.' },
