    assessmentTools: { rubric: ['السبب والمدة', 'القرار', 'الرجاء والنتيجة', 'الأفعال وحروفها'], exitTicket: ['اكتب جملة بـ«لعلّي… فـ…» عن خطتك للغد، وجملة بـ«احتاج إلى».'] },
