    assessmentTools: { rubric: ['سلسلة الأمر والتنفيذ والنتيجة', 'الآيات والمهمة', 'ضبط الأمر و«صار» و«أنْ»', 'النقل المترابط'], exitTicket: ['اكتب أمرًا ونتيجته من الفصل، وجملة تنقل تعليمات تلقّيتها: «أمرني المعلّم أنْ ____َ».'] },
