    expectedResponses: ['بدت عصيّ السحرة وحبالهم كأنها أفاعٍ، أما عصا موسى فتحوّلت إلى حيّة عظيمة ابتلعت ما صنعوه. فعرف السحرة أنّها ليست سحرًا فسجدوا لله وآمنوا، لكنّ فرعون ظلّ يرفض الإيمان لأنه كان متكبّرًا، واستمرّ في إيذاء موسى وقومه.'],
    transferTask: 'اكتب فقرة مقارنة يغيّر فيها فريق رأيه بعد دليل واضح، ويستمرّ شخص آخر في الرفض.',
    teacherReflection: 'هل حافظ المتعلمون على قوة كل تعبير كما هي («كأنّ» و«تحوّل إلى»)؟ وهل ربطوا التواضع بمراجعة الرأي بعد الدليل؟',
    assessmentTools: { rubric: ['المظهر والتغيّر الحقيقي', 'مقارنة الاستجابتين بالسبب', 'ضبط «ظلّ» و«استمرّ في» و«لأنّ»', 'التواضع في الموقف'], exitTicket: ['اكتب جملة بـ«بدا كأنّ» وجملة بـ«ظلّ + مضارع… لأنّ…» عن موقف تعرفه.'] },
